void LAi_ActivateReload()
{
	string controlName = GetEventData();
	if(controlName != "ChrAction") return;
	if (Boarding_CabinLootReady())
	{
		// The same click opens chests and searches bodies. Keep those actions local.
		if (dialogRun || sti(InterfaceStates.Launched) || LAi_IsFightMode(pchar)) return;
		if (CheckAttribute(pchar, "boxname")) return;
		if (CheckAttribute(pchar, "activeItem") && pchar.activeItem != "") return;
		if (Dead_FindCloseBody() >= 0) return;
	}
	DelEventHandler("Control Activation", "LAi_ActivateReload");
	Log_SetActiveAction("Nothing");
	LAi_ReloadBoarding();
}

