// Permanent progression must not depend on sickness or a ship-class penalty.
int Progression_GetPermanentSPECIAL(aref chr, string stat)
{
    int value = 3;
    if (CheckAttribute(chr, "SPECIAL." + stat)) value = sti(chr.SPECIAL.(stat));
    if (value < 1) value = 1;
    if (value > SPECIAL_MAX) value = SPECIAL_MAX;
    return value;
}

float Progression_MigrateHeroHP(aref chr, float baseHP)
{
    if (!CheckAttribute(chr, "index") || sti(chr.index) != GetMainCharacterIndex()) return baseHP;
    if (!CheckAttribute(chr, "SPECIAL." + SPECIAL_E) || !CheckAttribute(chr, "rank") || baseHP <= 0.0) return baseHP;
    if (CheckAttribute(chr, "Progression.HPCurve")) return baseHP;
    int rank = sti(chr.rank);
    if (rank < 1) rank = 1;
    int strength = Progression_GetPermanentSPECIAL(chr, SPECIAL_S);
    int endurance = Progression_GetPermanentSPECIAL(chr, SPECIAL_E);
    int previousBase = makeint(30.0 + strength * endurance * 0.5);
    int previousGain = makeint(2.0 + endurance * 0.55 + 0.5);
    int nextBase = 50 + strength + endurance;
    int nextGain = 6 + makeint((endurance + 2) / 3);
    float delta = nextBase - previousBase + (rank - 1) * (nextGain - previousGain);
    if (delta < 0.0) delta = 0.0;
    float oldMax = stf(chr.chr_ai.hp_max);
    float newMax = baseHP + delta;
    if (CheckCharacterPerk(chr, "HPPlus")) newMax = newMax + rank;
    if (CheckAttribute(chr, "chr_ai.hp") && oldMax > 0.0)
    {
        float fraction = stf(chr.chr_ai.hp) / oldMax;
        if (fraction < 0.0) fraction = 0.0;
        if (fraction > 1.0) fraction = 1.0;
        chr.chr_ai.hp = fraction * newMax;
    }
    chr.Progression.HPCurve = 1;
    return baseHP + delta;
}

